const CHUNK_SIZE = 1000;
const CHUNK_OVERLAP = 150;
const MIN_CHUNK_LENGTH = 30; // seuil minimum de caractères utiles

function splitText(text, chunkSize, overlap) {
  const cleaned = text.replace(/\n{3,}/g, '\n\n').trim();
  const chunks = [];
  let start = 0;

  while (start < cleaned.length) {
    let end = start + chunkSize;

    if (end < cleaned.length) {
      const lastBreak = cleaned.lastIndexOf('\n', end);
      const lastDot = cleaned.lastIndexOf('. ', end);
      const cut = Math.max(lastBreak, lastDot);
      if (cut > start + chunkSize * 0.5) {
        end = cut + 1;
      }
    }

    const chunk = cleaned.slice(start, end).trim();
    chunks.push(chunk);

    start = end - overlap;
    if (start <= 0 || end >= cleaned.length) break;
  }

  return chunks;
}

// Vérifie qu'un chunk contient un vrai contenu (pas que ponctuation/espaces)
function isValidChunk(chunk) {
  const alphanumeric = chunk.replace(/[^a-zA-Z0-9À-ÿ]/g, '');
  return alphanumeric.length >= MIN_CHUNK_LENGTH;
}

const results = [];

for (const item of items) {
  const text = item.json.text || '';
  if (!text.trim()) continue;

  const chunks = splitText(text, CHUNK_SIZE, CHUNK_OVERLAP);

  for (let i = 0; i < chunks.length; i++) {
    if (isValidChunk(chunks[i])) {
      results.push({
        json: {
          pageContent: chunks[i],
          metadata: {
            chunkIndex: i,
            source: item.json.fileName || 'healthy life.pdf'
          }
        }
      });
    }
  }
}

if (results.length === 0) {
  throw new Error('Aucun chunk valide généré — vérifie le texte extrait du PDF');
}

return results;
